#!/usr/bin/env python3
import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "WORKSPACE_MANIFEST.json"
CONTROL_ROOTS = [
    ROOT / "README.md",
    ROOT / "PREPARATION_REPORT.md",
    ROOT / "BASELINE_LOCK.json",
    ROOT / "WORKSPACE_STATUS.json",
    ROOT / "docs",
    ROOT / "requirements",
    ROOT / "control",
    ROOT / "scripts",
    ROOT / "sections",
    ROOT / "input",
]
EXCLUDED_PREFIXES = (
    "input/upstream_reference/reconstructed_runtime_source/",
    "input/upstream_reference/git-bundles/",
)
EXCLUDED_FILES = {
    "WORKSPACE_MANIFEST.json",
}


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def include(path: Path) -> bool:
    rel = path.relative_to(ROOT).as_posix()
    if rel in EXCLUDED_FILES or rel.endswith(".pyc") or "/__pycache__/" in f"/{rel}":
        return False
    return not any(rel.startswith(prefix) for prefix in EXCLUDED_PREFIXES)


def main() -> None:
    paths: set[Path] = set()
    for root in CONTROL_ROOTS:
        if root.is_file():
            paths.add(root)
        elif root.is_dir():
            paths.update(path for path in root.rglob("*") if path.is_file())
    records = []
    for path in sorted(paths, key=lambda item: item.relative_to(ROOT).as_posix()):
        if not include(path):
            continue
        records.append({
            "path": path.relative_to(ROOT).as_posix(),
            "sha256": sha256(path),
            "size_bytes": path.stat().st_size,
        })
    payload = {
        "schema_version": 2,
        "generated_at_utc": datetime.now(timezone.utc).isoformat(),
        "purpose": "Detect accidental drift in the prepared control plane and cached build inputs.",
        "exclusions": [
            "Generated runtime-reference source trees are verified by their own manifest.",
            "Generated Git bundles are verified with git bundle verify and separate hashes.",
            "Implementation source and runtime artifacts are mutable and intentionally excluded.",
        ],
        "files": records,
    }
    OUTPUT.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")
    print(f"Wrote {len(records)} immutable workspace records to {OUTPUT}")


if __name__ == "__main__":
    main()
